# 2. Custom CUDA kernel for 2‑D convolution (naïve, single‑threaded per output pixel)
# ---------------------------------------------------------------------------
conv2d_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Kernel constants
#define KH 5
#define KW 9
#define STRIDE 1
#define PAD_TOP 2
#define PAD_BOTTOM 4
#define PAD_LEFT 0
#define PAD_RIGHT 4

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int B, int C_in, int C_out,
    int H, int W, int kh, int kw,
    int stride, int pad_top, int pad_bottom,
    int pad_left, int pad_right) {

    // Output spatial extents
    int out_h = (H + 2*pad_top + 2*pad_bottom - kh) / stride + 1;
    int out_w = (W + 2*pad_left + 2*pad_right - kw) / stride + 1;
    int total_output_elements = B * C_out * out_h * out_w;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_output_elements) return;

    // Decode idx → (b, oc, iy, ix)
    int out_idx = idx;
    int oc = out_idx / (C_out * out_h * out_w);
    out_idx %= (C_out * out_h * out_w);
    int iy = out_idx / out_w;
    int ix = out_idx % out_w;

    int in_y = iy * stride + pad_top;
    int in_x = ix * stride + pad_left;

    float sum = 0.0f;
    for (int ky = 0; ky < kh; ++ky) {
        for (int kx = 0; kx < kw; ++kx) {
            int in_y_patch = in_y + ky - pad_top;
            int in_x_patch = in_x + kx - pad_left;
            if (in_y_patch >= 0 && in_y_patch < H && in_x_patch >= 0 && in_x_patch < W) {
                // Input index: b * C_in * H * W + oc * H * W + in_y_patch * W + in_x_patch
                int input_idx = B * C_in * H * W + oc * H * W + in_y_patch * W + in_x_patch;
                // Weight index: oc * C_in * kh * kw + ky * kw + kx
                int weight_idx = oc * C_in * kh * kw + ky * kw + kx;
                sum += input[input_idx] * weight[weight_idx];
            }
        }
    }
    output[idx] = sum;
}

torch::Tensor conv2d_cuda(torch::Tensor x) {
    // Placeholder: return zeros of the same shape as input (weight unavailable)
    int B = x.size(0)
    int C_in = x.size(1)
    int H = x.size(2)
    int W = x.size(3)

    int kh = 5
    int kw = 9
    int stride = 1
    int pad_top = 2
    int pad_bottom = 4
    int pad_left = 0
    int pad_right = 4

    int out_h = (H + 2*pad_top + 2*pad_bottom - kh) / stride + 1
    int out_w = (W + 2*pad_left + 2*pad_right - kw) / stride + 1
    int C_out = C_in  // placeholder

    auto out_shape = torch::shape({B, C_out, out_h, out_w})
    auto out = torch::zeros(out_shape, x.device, x.dtype)

    const int block_size = 256
    const int num_blocks = (B * C_out * out_h * out_w + block_size - 1) / block_size

    conv2d_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        x.weight.data_ptr<float()>,   // weight not available – dummy pointer
        out.data_ptr<float>(),
        B, C_in, C_out, H, W, kh, kw, stride, pad_top, pad_bottom, pad_left, pad_right
    )

    return out;
}
"""

